using Microsoft.AspNetCore.Http;
using MoveWell.Common.Cultures;

namespace MoveWell.Shared.Globalization.Routing;

/// <summary>
/// Turns the <c>/en</c> prefix into the request's <c>PathBase</c>: <c>/en/account/signin</c> is routed as <c>/account/signin</c>
/// with PathBase <c>/en</c>. Every route therefore exists once, and every link generated by MVC keeps the language
/// automatically (Url helpers prepend PathBase). Must run before routing.
/// </summary>
public sealed class CulturePrefixMiddleware
{
    private static readonly PathString EnPrefix = new("/" + Cultures.EnRoutePrefix);

    private readonly RequestDelegate _next;

    public CulturePrefixMiddleware(RequestDelegate next)
    {
        _next = next;
    }

    public Task InvokeAsync(HttpContext context)
    {
        if (context.Request.Path.StartsWithSegments(EnPrefix, StringComparison.OrdinalIgnoreCase, out var remaining))
        {
            context.Request.PathBase = context.Request.PathBase.Add(EnPrefix);
            context.Request.Path = remaining.HasValue ? remaining : new PathString("/");
        }

        return _next(context);
    }

    public static bool IsEnglish(HttpRequest request) =>
        request.PathBase.Value?.EndsWith(EnPrefix.Value!, StringComparison.OrdinalIgnoreCase) == true;
}
